"use client";
import { FlowDiagram } from "@diax/react";

export default function AnimatedEdges() {
  return (
    <FlowDiagram
      nodes={[
        { id: "src", content: "Source" },
        { id: "lint", content: "Lint" },
        { id: "test", content: "Test" },
        { id: "gate", content: "Quality Gate" },
        { id: "deploy", content: "Deploy" },
      ]}
      relations={[
        { from: "src", to: "lint", animate: "flow" },
        { from: "src", to: "test", animate: "flow" },
        { from: "lint", to: "gate", animate: "pulse", color: "#4CAF50" },
        { from: "test", to: "gate", animate: "pulse", color: "#4CAF50" },
        { from: "gate", to: "deploy", animate: "shimmer", color: "#5E6AD2" },
      ]}
      centered
      density="spacious"
    />
  );
}
